mkdir -p /app/output /app/tmp
cat > /app/tmp/ml_architecture.mmd <<'EOF'
%%{init: {"theme":"base", "darkMode": true, "flowchart": {"htmlLabels": true, "curve": "basis", "nodeSpacing": 56, "rankSpacing": 86, "padding": 18}, "themeVariables": {"background":"#0b1020", "mainBkg":"#111827", "primaryTextColor":"#f8fafc", "lineColor":"#94a3b8", "fontFamily":"Inter, Segoe UI, Arial, sans-serif", "clusterBkg":"#0f172a", "clusterBorder":"#334155", "titleColor":"#f8fafc"}}}%%
flowchart LR
  title["<b>ML Infrastructure Pipeline Architecture</b><br/><span style='font-size:14px'>Directed system flow with throughput (Gbps), criticality, lineage, and feedback loops</span>"]:::titleNode

  subgraph dataLayer["Data layer"]
    direction TB
    data_platform["<b>Data Platform</b><br/>Spark / Flink<br/><span>Criticality 9/10</span>"]:::dataCrit9
    feature_store["<b>Feature Store</b><br/>Online Redis + Offline Hive<br/><span>Criticality 8/10</span>"]:::dataCrit8
  end

  subgraph computeLayer["Compute layer"]
    direction TB
    training_cluster["<b>Training Cluster</b><br/>GPU / A100 Pool<br/><span>Criticality 10/10</span>"]:::computeCrit10
    model_registry["<b>Model Registry</b><br/>MLflow + S3 Artifacts<br/><span>Criticality 8/10</span>"]:::computeCrit8
  end

  subgraph servingLayer["Serving layer"]
    direction TB
    inference_online["<b>Inference Service</b><br/>Online / Real-time<br/><span>Criticality 9/10</span>"]:::servingCrit9
    inference_offline["<b>Inference Service</b><br/>Offline / Batch<br/><span>Criticality 7/10</span>"]:::servingCrit7
    ab_experiment["<b>A/B Experiment Platform</b><br/>Traffic split + stats engine<br/><span>Criticality 8/10</span>"]:::servingCrit8
  end

  subgraph obsLayer["Observability + cross-cutting control"]
    direction TB
    monitoring["<b>Monitoring & Alerting</b><br/>Prometheus / Grafana / PagerDuty<br/><span>Criticality 9/10</span>"]:::obsCrit9
    version_control["<b>Version Control & Data Lineage</b><br/>DVC / Git / Lineage Graph<br/><span>Criticality 7/10</span>"]:::obsCrit7
  end

  legend["<b>Legend</b><br/><span style='color:#60a5fa'>■ Data layer</span> &nbsp; <span style='color:#34d399'>■ Compute layer</span> &nbsp; <span style='color:#fb923c'>■ Serving layer</span> &nbsp; <span style='color:#f87171'>■ Observability</span><br/><b>Node size:</b> criticality score (7–10) &nbsp; | &nbsp; <b>Edge width:</b> throughput volume in Gbps<br/><span style='border-bottom:3px solid #e5e7eb'>Primary / feedback flow</span> &nbsp; | &nbsp; <span style='border-bottom:3px dashed #c084fc'>Lineage / version-control overlay</span>"]:::legendNode

  title ~~~ data_platform
  data_platform -->|"Raw → Features • 12.5 Gbps"| feature_store
  feature_store -->|"Training Data • 8.0 Gbps"| training_cluster
  training_cluster -->|"Trained Models • 2.5 Gbps"| model_registry
  model_registry -->|"Model Deploy Online • 1.8 Gbps"| inference_online
  model_registry -->|"Model Deploy Batch • 3.2 Gbps"| inference_offline
  feature_store -->|"Online Features • 6.0 Gbps"| inference_online
  inference_online -->|"Predictions RT • 5.0 Gbps"| ab_experiment
  inference_offline -->|"Predictions Batch • 4.0 Gbps"| ab_experiment
  ab_experiment -->|"Metrics & Results • 2.0 Gbps"| monitoring
  monitoring -->|"Data Quality Alerts • 0.5 Gbps"| data_platform
  monitoring -->|"Retrain Trigger • 0.3 Gbps"| training_cluster
  data_platform -.->|"Data Lineage • 0.2 Gbps"| version_control
  version_control -.->|"Feature Versioning • 0.1 Gbps"| feature_store
  version_control -.->|"Experiment Tracking • 0.1 Gbps"| training_cluster
  version_control -.->|"Model Lineage • 0.1 Gbps"| model_registry
  legend ~~~ monitoring

  classDef titleNode fill:#0b1020,stroke:#0b1020,color:#f8fafc,font-size:30px,font-weight:bold;
  classDef legendNode fill:#111827,stroke:#64748b,stroke-width:1.5px,color:#e5e7eb,font-size:15px;
  classDef dataCrit9 fill:#1d4ed8,stroke:#93c5fd,stroke-width:4px,color:#eff6ff,font-size:20px;
  classDef dataCrit8 fill:#2563eb,stroke:#93c5fd,stroke-width:3px,color:#eff6ff,font-size:18px;
  classDef computeCrit10 fill:#047857,stroke:#a7f3d0,stroke-width:5px,color:#ecfdf5,font-size:22px;
  classDef computeCrit8 fill:#059669,stroke:#a7f3d0,stroke-width:3px,color:#ecfdf5,font-size:18px;
  classDef servingCrit9 fill:#c2410c,stroke:#fed7aa,stroke-width:4px,color:#fff7ed,font-size:20px;
  classDef servingCrit8 fill:#ea580c,stroke:#fed7aa,stroke-width:3px,color:#fff7ed,font-size:18px;
  classDef servingCrit7 fill:#f97316,stroke:#fed7aa,stroke-width:2px,color:#fff7ed,font-size:16px;
  classDef obsCrit9 fill:#b91c1c,stroke:#fecaca,stroke-width:4px,color:#fef2f2,font-size:20px;
  classDef obsCrit7 fill:#7f1d1d,stroke:#fca5a5,stroke-width:2px,color:#fef2f2,font-size:16px;

  linkStyle 0 stroke:#0b1020,stroke-width:0px;
  linkStyle 1 stroke:#e5e7eb,stroke-width:9px,color:#f8fafc;
  linkStyle 2 stroke:#e5e7eb,stroke-width:7px,color:#f8fafc;
  linkStyle 3 stroke:#e5e7eb,stroke-width:4px,color:#f8fafc;
  linkStyle 4 stroke:#e5e7eb,stroke-width:3px,color:#f8fafc;
  linkStyle 5 stroke:#e5e7eb,stroke-width:4px,color:#f8fafc;
  linkStyle 6 stroke:#e5e7eb,stroke-width:6px,color:#f8fafc;
  linkStyle 7 stroke:#e5e7eb,stroke-width:5.5px,color:#f8fafc;
  linkStyle 8 stroke:#e5e7eb,stroke-width:5px,color:#f8fafc;
  linkStyle 9 stroke:#fbbf24,stroke-width:3px,color:#fde68a;
  linkStyle 10 stroke:#f87171,stroke-width:2.5px,color:#fecaca;
  linkStyle 11 stroke:#f87171,stroke-width:2.5px,color:#fecaca;
  linkStyle 12 stroke:#c084fc,stroke-width:2px,stroke-dasharray:8 6,color:#e9d5ff;
  linkStyle 13 stroke:#c084fc,stroke-width:2px,stroke-dasharray:8 6,color:#e9d5ff;
  linkStyle 14 stroke:#c084fc,stroke-width:2px,stroke-dasharray:8 6,color:#e9d5ff;
  linkStyle 15 stroke:#c084fc,stroke-width:2px,stroke-dasharray:8 6,color:#e9d5ff;
  linkStyle 16 stroke:#0b1020,stroke-width:0px;
EOF
cat > /app/tmp/puppeteer-config.json <<'EOF'
{
  "args": ["--no-sandbox", "--disable-setuid-sandbox", "--disable-dev-shm-usage"]
}
EOF
mmdc -i /app/tmp/ml_architecture.mmd -o /app/output/result.png -b '#0b1020' -w 2200 -H 1350 -p /app/tmp/puppeteer-config.json

